from .exceptions import InvalidStatus
from .status.detected_status import DetectedStatus
from .status.expected_status import ExpectedStatus
from .status.existing_status import ExistingStatus
from .status.lost_status import LostStatus


class StatusFactory(object):
    _INVALID_DATA_ERROR_MSG_TEMPLATE = "Cannot create status with {}='{}'"

    @classmethod
    def create_expected_status(cls, component, name, value):
        """
        Creates new expected status with given status data.

        :param component: runtime distName of component for which given status should be expected
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param name: name of expected status, i.e. 'availabilityStatus'
        :type name: str
        :param value: value of expected status, i.e. 'Offline';
                      use None when expecting status without value (i.e. 'Online' after CNI-61110)
        :type value: str or None
        :return: expected status
        :rtype: ExpectedStatus
        :raises InvalidStatus: when invalid status data provided
        """
        cls._validate_component(component)
        cls._validate_name(name)
        cls._validate_value(value)
        return ExpectedStatus(component=component, name=name, value=value)

    @classmethod
    def create_existing_status(cls, component, name, admin_response):
        """
        Creates new existing status with given status data.

        :param component: runtime distName of existing status component
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param name: name of existing status, i.e. 'availabilityStatus'
        :type name: str
        :param admin_response: BTS response containing value of existing status,
                               i.e. {'stateInfo': {'availabilityStatus': 'Offline'}};
                               value=None will be used if BTS response doesn't contain given status name
        :type admin_response: {str: str or {str: str}}
        :return: existing status
        :rtype: ExistingStatus
        :raises InvalidStatus: when invalid status data provided
        """
        cls._validate_component(component)
        cls._validate_name(name)
        cls._validate_admin_response(admin_response)

        return ExistingStatus(component=component,
                              name=name,
                              value=cls._get_value_from_admin_response(admin_response, name))

    @classmethod
    def create_detected_status(cls, component, name, value):
        """
        Creates new detected status with given status data.

        :param component: runtime distName of component for which given status was detected
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param name: name of detected status, i.e. 'availabilityStatus'
        :type name: str
        :param value: value of detected status, i.e. 'Offline';
                      use None when detected status has no value (i.e. 'Online' after CNI-61110)
        :type value: str or None
        :return: detected status
        :rtype: DetectedStatus
        :raises InvalidStatus: when invalid status data provided
        """
        cls._validate_component(component)
        cls._validate_name(name)
        cls._validate_value(value)
        return DetectedStatus(component=component, name=name, value=value)

    @classmethod
    def create_lost_status(cls, component, name, value):
        """
        Creates new lost status with given status data.

        :param component: runtime distName of component for which given status was lost
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param name: name of lost status, i.e. 'availabilityStatus'
        :type name: str
        :param value: value of lost status, i.e. 'Offline';
                      use None when lost status has no value (i.e. 'Online' after CNI-61110)
        :type value: str or None
        :return: lost status
        :rtype: LostStatus
        :raises InvalidStatus: when invalid status data provided
        """
        cls._validate_component(component)
        cls._validate_name(name)
        cls._validate_value(value)
        return LostStatus(component=component, name=name, value=value)

    @classmethod
    def _validate_component(cls, component):
        if not component:
            raise InvalidStatus(cls._INVALID_DATA_ERROR_MSG_TEMPLATE.format('component', component))

    @classmethod
    def _validate_name(cls, name):
        if not name:
            raise InvalidStatus(cls._INVALID_DATA_ERROR_MSG_TEMPLATE.format('name', name))

    @classmethod
    def _validate_value(cls, value):
        if value == '':
            raise InvalidStatus(cls._INVALID_DATA_ERROR_MSG_TEMPLATE.format('value', value))

    @classmethod
    def _validate_admin_response(cls, admin_response):
        if not admin_response or ('stateInfo' in admin_response and not admin_response['stateInfo']):
            raise InvalidStatus(cls._INVALID_DATA_ERROR_MSG_TEMPLATE.format('admin_response', admin_response))

    @classmethod
    def _get_value_from_admin_response(cls, admin_response, name):
        return admin_response['stateInfo'].get(name, None) if 'stateInfo' in admin_response else \
            admin_response.get(name, None)
